impl FibrationIntegrityCard7{pub fn validate(&self)->Result<(),FibrationIntegrityError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.region_order.is_empty()||!ordered(&self.region_order)||!ordered(&self.accepted_order)||!ordered(&self.rejected_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.factor_order)||!ordered(&self.scope_order)||!ordered(&self.epoch_order)||!ordered(&self.negative_evidence_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(FibrationIntegrityError::Output("fibration identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.region_order.iter().cloned());let states=self.accepted_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.region_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(FibrationIntegrityError::Output("region states do not partition".into()))}Ok(())}}
pub fn certify(request:&FibrationIntegrityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<FibrationIntegrityCard7,FibrationIntegrityError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.regions.is_empty()||request.required_region_order.is_empty()||request.required_factor_order.is_empty()||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_region_order)||!ordered(&request.required_factor_order)||!ordered(&request.adversarial_events){return Err(FibrationIntegrityError::Invalid("fibration identity, requirements, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.regions.clone();rows.sort_by(|a,b|a.region_id.cmp(&b.region_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut factors=BTreeSet::new();let mut scopes=BTreeSet::new();let mut epochs=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for r in &rows{if !seen.insert(r.region_id.clone())||!nonempty(&r.region_id)||!nonempty(&r.section_id)||r.factor_order.is_empty()||!ordered(&r.factor_order)||!digest(&r.evidence_digest)||!nonempty(&r.scope_id)||!r.local||!r.aggregate_only{return Err(FibrationIntegrityError::Invalid("region identity, factor ordering, evidence, or locality is invalid".into()))}order.push(r.region_id.clone());factors.extend(r.factor_order.iter().cloned());scopes.insert(r.scope_id.clone());epochs.insert(format!("{}:{}",r.scope_id,r.policy_epoch));digests.insert(r.evidence_digest.clone());if r.negative_result{negative.insert(format!("{}:negative-result",r.region_id));}if r.policy_epoch==0{unknown.insert(r.region_id.clone());}else if !request.required_region_order.contains(&r.region_id)||!request.required_factor_order.iter().all(|f|r.factor_order.contains(f)){rejected.insert(r.region_id.clone());}else if r.evidence_digest==request.replay_identity{omitted.insert(r.region_id.clone());}else{accepted.insert(r.region_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let missing=!request.required_region_order.iter().all(|r|seen.contains(r))||!request.required_factor_order.iter().all(|f|factors.contains(f));let disposition=if global{"blocked"}else if missing{"unknown"}else if !rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"region_order":order,"accepted_order":accepted.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"factor_order":factors.into_iter().collect::<Vec<_>>(),"scope_order":scopes.into_iter().collect::<Vec<_>>(),"epoch_order":epochs.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|FibrationIntegrityError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("fiber-fibration:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"region_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:fibration-card:{}",request.request_id)]}else{vec!["block:unsafe-compilation".to_string()]});let out:FibrationIntegrityCard7=serde_json::from_value(payload).map_err(|e|FibrationIntegrityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
